'use strict';
// MCP completeness M2, spec section 4, the golden rule's second golden: the
// tools/list surface of the fixture that declares everything
// (test/fixtures/declares-everything) -- its titles, annotations and inlined
// icon included -- byte for byte, in both eras, in worker and single-thread
// mode alike. tools-list.golden.json (01) is never regenerated by this spec.
// Regenerate this one only when the fixture's tool surface is meant to
// change: node test/mcp-contract/capture-tools-list-everything.js
const assert = require('assert');
const fs = require('fs');
const {capture, GOLDEN} = require('./capture-tools-list-everything');

describe('mcp-contract 23: the second golden, the fixture that declares everything (M2)', function() {
  this.timeout(180000);
  const golden = fs.readFileSync(GOLDEN, 'utf8');
  const parsed = JSON.parse(golden);

  it('the golden holds what M2 adds: a title, annotations and an inlined icon, after the old keys', () => {
    const read = parsed.legacy.find((t) => /readnote$/.test(t.name));
    assert.deepStrictEqual(Object.keys(read).slice(-3), ['title', 'annotations', 'icons']);
    assert.match(read.icons[0].src, /^data:image\/png;base64,/);
  });

  for (const workerThread of [true, false]) {
    it(`${workerThread ? 'worker' : 'single-thread'} mode: both eras are the golden, byte for byte`, async () => {
      const got = await capture({workerThread});
      assert.strictEqual(`${JSON.stringify(got, null, 2)}\n`, golden);
    });
  }
});
